import SwiftUI
import UIKit

// MARK: - Deep Link Types
enum DeepLink: Equatable {
    case home
    case startFocus(duration: Int)
    case constellation
    case analytics
    case settings
    case premium
    case achievement(id: String)
    case scheduledSession(id: String)
    case shareResult(minutes: Int, plants: Int)

    var url: URL? {
        switch self {
        case .home:
            return URL(string: "focusflow://home")
        case .startFocus(let duration):
            return URL(string: "focusflow://start/\(duration)")
        case .constellation:
            return URL(string: "focusflow://constellation")
        case .analytics:
            return URL(string: "focusflow://analytics")
        case .settings:
            return URL(string: "focusflow://settings")
        case .premium:
            return URL(string: "focusflow://premium")
        case .achievement(let id):
            return URL(string: "focusflow://achievement/\(id)")
        case .scheduledSession(let id):
            return URL(string: "focusflow://session/\(id)")
        case .shareResult(let minutes, let plants):
            return URL(string: "focusflow://share?minutes=\(minutes)&plants=\(plants)")
        }
    }
}

