// MARK: - Error Alert View
struct ErrorAlertView: ViewModifier {
    @ObservedObject var errorHandler = GlobalErrorHandler.shared

    func body(content: Content) -> some View {
        content
            .alert("Error", isPresented: $errorHandler.showErrorAlert) {
                Button("OK") {
                    errorHandler.clearCurrentError()
                }

                if let error = errorHandler.currentError,
                   error.severity == .critical {
                    Button("Report Issue") {
                        reportIssue(error)
                    }
                }
            } message: {
                if let error = errorHandler.currentError {
                    VStack {
                        Text(error.localizedDescription)
                        if let suggestion = error.recoverySuggestion {
                            Text(suggestion)
                                .font(.caption)
                        }
                    }
                }
            }
    }

    private func reportIssue(_ error: FocusFlowError) {
        // Implement issue reporting
        let errorDetails = """
        Error: \(error.localizedDescription)
        Time: \(Date())
        Suggestion: \(error.recoverySuggestion ?? "None")
        """

        #if DEBUG
        print("Error Report:\n\(errorDetails)")
        #endif
    }
}

// MARK: - View Extension
extension View {
    func withErrorHandling() -> some View {
        self.modifier(ErrorAlertView())
    }
}

