struct LazyScreenContainer<Content: View>: View {
    let screenIndex: Int
    @Binding var currentScreen: Int
    let content: () -> Content

    init(screenIndex: Int, currentScreen: Binding<Int>, @ViewBuilder content: @escaping () -> Content) {
        self.screenIndex = screenIndex
        self._currentScreen = currentScreen
        self.content = content
        onboardingLog("🟦 [LazyScreenContainer] INIT - screenIndex: \(screenIndex), currentScreen: \(currentScreen.wrappedValue)")
    }

    var body: some View {
        // Simply pass through the content - the actual lazy loading logic is in PremiumOnboardingView
        content()
            .onAppear {
                if abs(screenIndex - currentScreen) <= 1 {
                    onboardingLog("🟦 [LazyScreenContainer] Content appeared for screen \(screenIndex) (current: \(currentScreen))")
                } else {
                    onboardingLog("🟦 [LazyScreenContainer] Placeholder for screen \(screenIndex) (current: \(currentScreen))")
                }
            }
    }
}

