// MARK: - SwiftData Container Configuration
extension ModelContainer {
    @MainActor
    static var production: ModelContainer {
        let container = ModelContainerFactory.shared.create(isStoredInMemoryOnly: false)

        // Run migration if needed
        Task {
            do {
                try await DataMigrationManager.shared.migrateFromUserDefaults(to: container)
            } catch {
                print("Migration error: \(error)")
            }
        }

        return container
    }

    @MainActor
    static var preview: ModelContainer {
        let container = ModelContainerFactory.shared.create(isStoredInMemoryOnly: true)

        // Add sample data for previews
        do {
            let context = ModelContext(container)
            let user = UserProfile(name: "Preview User")
            context.insert(user)

            // Add sample sessions
            for i in 0..<5 {
                let session = FocusSessionData(
                    plannedDuration: 25,
                    difficulty: "normal",
                    sessionType: "manual"
                )
                session.isCompleted = true
                session.actualDuration = 25
                session.startTime = Date().addingTimeInterval(TimeInterval(-i * 86400))
                session.user = user
                context.insert(session)
            }

            try context.save()
        } catch {
            print("Error adding preview data: \(error)")
        }

        return container
    }
}

